                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Simulated study
#'
#' Simulates a plausible medical study for teaching: a clinical scenario from 
#' the library, a study design compatible with its outcome, a sample size and 
#' some realism. The dataset opens in a new window; the answer key holds the 
#' true parameters and what the design is expected to estimate.
#' 
#'
#' @examples
#' \donttest{
#' # in R, use the engine directly:
#' # sc <- studysim:::load_scenario(studysim:::builtin_library(), "chd_incidence")
#' # studysim:::simulate_study(sc, "chd", "cohort", n = 1000)
#'}
#' @param data .
#' @param libName name of the custom library file read by the Browse button
#'   (display only)
#' @param libContent base64 of the custom library file (JSON, YAML, Excel or
#'   zip)
#' @param scenario scenario id
#' @param outcome outcome id; empty means the scenario's first outcome
#' @param design study design; must fit the outcome
#' @param measured one entry per scenario variable, list(var = name, include =
#'   TRUE/FALSE, form =
#'   "continuous"/"median"/"tertiles"/"quartiles"/"quintiles"/"cuts", cuts =
#'   "18.5, 25, 30" or "10\%, 90\%"); included variables are in the dataset, the
#'   others are unmeasured (they still act); form groups a continuous variable
#'   (quantiles from the sample)
#' @param n number of participants (cases plus controls in case-control
#'   designs)
#' @param ccRatio .
#' @param followup 0 uses the scenario's default
#' @param loss .
#' @param accrual 0 uses the design's default (staggered entry for prognosis)
#' @param period .
#' @param carryover .
#' @param missing .
#' @param missingMech .
#' @param seed .
#' @param studentKey any text (e.g. a student ID); each key gives a different
#'   dataset
#' @param showDictionary .
#' @param showDescriptives .
#' @param showDag .
#' @param dagValues .
#' @param showKey .
#' @param openData .
#' @param exportCsv .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$notice} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dictionary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptives} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dag} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$keyEffects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyExpected} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyNotes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$openState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$csvState} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$dictionary$asDF}
#'
#' \code{as.data.frame(results$dictionary)}
#'
#' @export
simStudy <- function(
    data,
    libName = "",
    libContent = "",
    scenario = "breast_cancer_risk",
    outcome = "",
    design = "case_control",
    measured = list(),
    n = 500,
    ccRatio = 1,
    followup = 0,
    loss = 2,
    accrual = 0,
    period = 0,
    carryover = 0,
    missing = 0,
    missingMech = "mcar",
    seed = 1,
    studentKey = "",
    showDictionary = TRUE,
    showDescriptives = TRUE,
    showDag = FALSE,
    dagValues = FALSE,
    showKey = FALSE,
    openData = FALSE,
    exportCsv = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("simStudy requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- simStudyOptions$new(
        libName = libName,
        libContent = libContent,
        scenario = scenario,
        outcome = outcome,
        design = design,
        measured = measured,
        n = n,
        ccRatio = ccRatio,
        followup = followup,
        loss = loss,
        accrual = accrual,
        period = period,
        carryover = carryover,
        missing = missing,
        missingMech = missingMech,
        seed = seed,
        studentKey = studentKey,
        showDictionary = showDictionary,
        showDescriptives = showDescriptives,
        showDag = showDag,
        dagValues = dagValues,
        showKey = showKey,
        openData = openData,
        exportCsv = exportCsv)

    analysis <- simStudyClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

